-- V1: Reviews table.
-- One review per (user, property) is enforced at the schema level. This keeps
-- the addReview duplicate-error path deterministic regardless of caller race.

CREATE TABLE reviews (
    id          UUID         PRIMARY KEY,
    property_id UUID         NOT NULL,
    user_id     UUID         NOT NULL,
    rating      SMALLINT     NOT NULL CHECK (rating BETWEEN 1 AND 5),
    comment     VARCHAR(2048) NOT NULL,
    created_at  TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW(),
    CONSTRAINT uq_reviews_property_user UNIQUE (property_id, user_id)
);

CREATE INDEX idx_reviews_property ON reviews (property_id);
CREATE INDEX idx_reviews_user     ON reviews (user_id);

-- 50 seed reviews: each of the 10 seeded users reviews 5 distinct properties.
-- Distribution gives every property at least 2 reviews so the reviewSummary
-- query always has data to aggregate.
